{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2144-06-28 11:00:00",
      "speaker": "Doctor",
      "text": "Good morning, Mr. ___. I’m Dr. ___, your urologist. You’re here today for your ileal conduit surgery. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2144-06-28 11:02:00",
      "speaker": "Patient",
      "text": "I’m okay, just nervous. This is a big surgery, right?"
    },
    {
      "turn_number": 3,
      "time": "2144-06-28 11:03:00",
      "speaker": "Doctor",
      "text": "It is, but it’s also very necessary. Your incontinence has been causing serious skin breakdown, and this surgery should help stop that."
    },
    {
      "turn_number": 4,
      "time": "2144-06-28 11:04:00",
      "speaker": "Patient",
      "text": "Yeah, the sores on my hip won’t heal. I just want this fixed."
    },
    {
      "turn_number": 5,
      "time": "2144-06-28 11:05:00",
      "speaker": "Doctor",
      "text": "We’ll take care of it. The plan is to create a new way for urine to leave your body using a piece of your intestine. You’ll have a stoma on your belly."
    },
    {
      "turn_number": 6,
      "time": "2144-06-28 11:06:00",
      "speaker": "Patient",
      "text": "And no more catheter down there?"
    },
    {
      "turn_number": 7,
      "time": "2144-06-28 11:07:00",
      "speaker": "Doctor",
      "text": "That’s right. The catheter has been causing leakage and irritation. This new system should stop that completely."
    },
    {
      "turn_number": 8,
      "time": "2144-06-28 11:08:00",
      "speaker": "Patient",
      "text": "Okay, I trust you. When do we start?"
    },
    {
      "turn_number": 9,
      "time": "2144-06-28 11:09:00",
      "speaker": "Doctor",
      "text": "You’ll be taken to the OR shortly. We’ll see you when you wake up in recovery."
    },
    {
      "turn_number": 10,
      "time": "2144-06-29 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You made it through surgery fine. You now have an ileal conduit. There are stents in place to help the connections heal."
    },
    {
      "turn_number": 11,
      "time": "2144-06-29 09:02:00",
      "speaker": "Patient",
      "text": "How’s the stoma looking?"
    },
    {
      "turn_number": 12,
      "time": "2144-06-29 09:03:00",
      "speaker": "Doctor",
      "text": "Pink, moist, and draining well—perfect. You also have a PICC line now because your veins were hard to access. It’ll help with antibiotics and fluids."
    },
    {
      "turn_number": 13,
      "time": "2144-06-29 09:05:00",
      "speaker": "Patient",
      "text": "I don’t like needles. Can’t I just take pills?"
    },
    {
      "turn_number": 14,
      "time": "2144-06-29 09:06:00",
      "speaker": "Doctor",
      "text": "Not right now. Your kidney function is reduced, and we need to make sure the antibiotics work. The PICC line helps us give them safely."
    },
    {
      "turn_number": 15,
      "time": "2144-06-30 10:15:00",
      "speaker": "Doctor",
      "text": "Your labs are improving. Hemoglobin was low yesterday, but it’s coming up. We’re watching your creatinine closely."
    },
    {
      "turn_number": 16,
      "time": "2144-06-30 10:17:00",
      "speaker": "Patient",
      "text": "My stomach feels bloated. Is that normal?"
    },
    {
      "turn_number": 17,
      "time": "2144-06-30 10:18:00",
      "speaker": "Doctor",
      "text": "Yes, your bowels are still waking up after surgery. You have an NG tube to help with that. We’ll remove it once things start moving."
    },
    {
      "turn_number": 18,
      "time": "2144-07-01 08:30:00",
      "speaker": "Doctor",
      "text": "Great news—your NG tube came out this morning. You passed the clamp trial, so no more suction."
    },
    {
      "turn_number": 19,
      "time": "2144-07-01 08:32:00",
      "speaker": "Patient",
      "text": "Can I eat now?"
    },
    {
      "turn_number": 20,
      "time": "2144-07-01 08:33:00",
      "speaker": "Doctor",
      "text": "We’ll start with clear liquids and see how you do. If no nausea, we’ll advance your diet."
    },
    {
      "turn_number": 21,
      "time": "2144-07-02 07:00:00",
      "speaker": "Doctor",
      "text": "You had a fever last night—102.5. We’re checking cultures and getting a CT to make sure there’s no infection."
    },
    {
      "turn_number": 22,
      "time": "2144-07-02 07:02:00",
      "speaker": "Patient",
      "text": "Is something wrong with the surgery?"
    },
    {
      "turn_number": 23,
      "time": "2144-07-02 07:04:00",
      "speaker": "Doctor",
      "text": "The CT showed normal post-op changes—no abscess or pneumonia. But your urine culture grew E. coli, so we’re starting antibiotics as a precaution."
    },
    {
      "turn_number": 24,
      "time": "2144-07-02 07:06:00",
      "speaker": "Patient",
      "text": "E. coli again? I’ve had that before."
    },
    {
      "turn_number": 25,
      "time": "2144-07-02 07:07:00",
      "speaker": "Doctor",
      "text": "Yes, and because of your history of resistant infections, we’re using meropenem. It’s strong but safe for your kidneys."
    },
    {
      "turn_number": 26,
      "time": "2144-07-03 09:10:00",
      "speaker": "Doctor",
      "text": "Your white count is coming down. That’s a good sign the antibiotics are working."
    },
    {
      "turn_number": 27,
      "time": "2144-07-03 09:12:00",
      "speaker": "Patient",
      "text": "I still feel tired."
    },
    {
      "turn_number": 28,
      "time": "2144-07-03 09:13:00",
      "speaker": "Doctor",
      "text": "Recovery takes time. Your body’s healing. We’ll keep helping with pain and nutrition."
    },
    {
      "turn_number": 29,
      "time": "2144-07-04 10:00:00",
      "speaker": "Doctor",
      "text": "The CT confirmed no abscess or osteomyelitis. Your fever is likely from the surgical site reacting, not a deep infection."
    },
    {
      "turn_number": 30,
      "time": "2144-07-04 10:02:00",
      "speaker": "Patient",
      "text": "What about my hip sore? No one’s looked at it."
    },
    {
      "turn_number": 31,
      "time": "2144-07-04 10:04:00",
      "speaker": "Doctor",
      "text": "We’ve asked wound care and plastics to help. They recommend a bedside debridement to help it heal."
    },
    {
      "turn_number": 32,
      "time": "2144-07-05 08:45:00",
      "speaker": "Doctor",
      "text": "You’re doing better. Your diet’s advanced to soft foods, and you’re managing pain with oral meds now."
    },
    {
      "turn_number": 33,
      "time": "2144-07-05 08:47:00",
      "speaker": "Patient",
      "text": "I took my oxycodone this morning. It helped."
    },
    {
      "turn_number": 34,
      "time": "2144-07-05 08:48:00",
      "speaker": "Doctor",
      "text": "Good. The chronic pain team adjusted your plan so you’re not on the IV PCA anymore."
    },
    {
      "turn_number": 35,
      "time": "2144-07-06 09:20:00",
      "speaker": "Doctor",
      "text": "Your white count is down to 17.9, and creatinine is stable. You’re healing well."
    },
    {
      "turn_number": 36,
      "time": "2144-07-06 09:22:00",
      "speaker": "Patient",
      "text": "Can I go home soon?"
    },
    {
      "turn_number": 37,
      "time": "2144-07-06 09:23:00",
      "speaker": "Doctor",
      "text": "Not yet. You still need IV antibiotics for a few more days. But we’re getting close."
    },
    {
      "turn_number": 38,
      "time": "2144-07-07 10:30:00",
      "speaker": "Doctor",
      "text": "Your latest urine culture showed yeast. It’s common after antibiotics. We don’t need to treat it unless you have symptoms."
    },
    {
      "turn_number": 39,
      "time": "2144-07-07 10:32:00",
      "speaker": "Patient",
      "text": "Is that serious?"
    },
    {
      "turn_number": 40,
      "time": "2144-07-07 10:33:00",
      "speaker": "Doctor",
      "text": "No, not at all. Just something we monitor. Your blood cultures were negative, so no bloodstream infection."
    },
    {
      "turn_number": 41,
      "time": "2144-07-08 08:15:00",
      "speaker": "Doctor",
      "text": "Almost there. One more dose of IV antibiotics tomorrow. Your stoma is healthy, and the wound is clean."
    },
    {
      "turn_number": 42,
      "time": "2144-07-08 08:17:00",
      "speaker": "Patient",
      "text": "I’ve been practicing with the ostomy bag. It’s weird, but I think I can manage."
    },
    {
      "turn_number": 43,
      "time": "2144-07-08 08:18:00",
      "speaker": "Doctor",
      "text": "You’re doing great. The nurse will keep teaching you, and you’ll have visiting nurses at home."
    },
    {
      "turn_number": 44,
      "time": "2144-07-09 08:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day. We’ll remove the stents and your PICC line. Then you can go home."
    },
    {
      "turn_number": 45,
      "time": "2144-07-09 08:02:00",
      "speaker": "Patient",
      "text": "Both today?"
    },
    {
      "turn_number": 46,
      "time": "2144-07-09 08:03:00",
      "speaker": "Doctor",
      "text": "Yes. The stents have done their job. We’ll take them out at the bedside. The PICC comes out after your last antibiotic dose."
    },
    {
      "turn_number": 47,
      "time": "2144-07-09 09:30:00",
      "speaker": "Doctor",
      "text": "Stents are out. You did great. No pain, right?"
    },
    {
      "turn_number": 48,
      "time": "2144-07-09 09:32:00",
      "speaker": "Patient",
      "text": "Felt a little pressure, but okay."
    },
    {
      "turn_number": 49,
      "time": "2144-07-09 10:15:00",
      "speaker": "Doctor",
      "text": "PICC line is out. The site’s covered, and you can shower in a couple days."
    },
    {
      "turn_number": 50,
      "time": "2144-07-09 10:17:00",
      "speaker": "Patient",
      "text": "What meds do I take at home?"
    },
    {
      "turn_number": 51,
      "time": "2144-07-09 10:19:00",
      "speaker": "Doctor",
      "text": "You’ll restart most of your home meds. We’re adding Bactrim for seven days to prevent infection and Vesicare to help with bladder spasms."
    },
    {
      "turn_number": 52,
      "time": "2144-07-09 10:21:00",
      "speaker": "Patient",
      "text": "I’m allergic to Bactrim."
    },
    {
      "turn_number": 53,
      "time": "2144-07-09 10:22:00",
      "speaker": "Doctor",
      "text": "I see that. We discussed it. The benefit outweighs the risk, and we’ll watch you closely. But you refused to start it here."
    },
    {
      "turn_number": 54,
      "time": "2144-07-09 10:24:00",
      "speaker": "Patient",
      "text": "I’ll take it at home if I have to."
    },
    {
      "turn_number": 55,
      "time": "2144-07-09 10:25:00",
      "speaker": "Doctor",
      "text": "Okay. Just call us if you develop a rash or fever."
    },
    {
      "turn_number": 56,
      "time": "2144-07-09 11:00:00",
      "speaker": "Doctor",
      "text": "Your staples are out, replaced with Steri-Strips. Keep the area dry for now."
    },
    {
      "turn_number": 57,
      "time": "2144-07-09 11:02:00",
      "speaker": "Patient",
      "text": "And the hip sore?"
    },
    {
      "turn_number": 58,
      "time": "2144-07-09 11:03:00",
      "speaker": "Doctor",
      "text": "It’s not infected, but it’s slow to heal. Plastics will see you as an outpatient. Keep using the special dressing."
    },
    {
      "turn_number": 59,
      "time": "2144-07-09 11:30:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. Your mom and goddaughter are here. Visiting nurses will help with your stoma and therapy."
    },
    {
      "turn_number": 60,
      "time": "2144-07-09 11:32:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel better already."
    },
    {
      "turn_number": 61,
      "time": "2144-07-09 11:34:00",
      "speaker": "Doctor",
      "text": "You did well. Remember: no heavy lifting, keep the incision dry, and call us if you have fever, redness, or pain."
    },
    {
      "turn_number": 62,
      "time": "2144-07-09 11:36:00",
      "speaker": "Patient",
      "text": "And follow-up?"
    },
    {
      "turn_number": 63,
      "time": "2144-07-09 11:37:00",
      "speaker": "Doctor",
      "text": "Urology in two weeks. Plastics and primary care will also see you. Take care, Mr. ___."
    },
    {
      "turn_number": 64,
      "time": "2144-07-09 11:38:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 65,
      "time": "2144-07-09 12:00:00",
      "speaker": "Doctor",
      "text": "The stents and PICC line are fully removed. You’re officially discharged."
    },
    {
      "turn_number": 66,
      "time": "2144-07-09 12:02:00",
      "speaker": "Patient",
      "text": "I’m ready to go home."
    },
    {
      "turn_number": 67,
      "time": "2144-07-09 12:03:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. Keep up the good work with your care team."
    },
    {
      "turn_number": 68,
      "time": "2144-07-09 12:05:00",
      "speaker": "Patient",
      "text": "I will. Appreciate everything."
    },
    {
      "turn_number": 69,
      "time": "2144-07-09 12:07:00",
      "speaker": "Doctor",
      "text": "Take these discharge instructions and the ostomy guide. Call us with any concerns."
    },
    {
      "turn_number": 70,
      "time": "2144-07-09 12:09:00",
      "speaker": "Patient",
      "text": "Got it. I’ll read them tonight."
    },
    {
      "turn_number": 71,
      "time": "2144-07-09 12:10:00",
      "speaker": "Doctor",
      "text": "Safe travels. We’ll see you soon."
    },
    {
      "turn_number": 72,
      "time": "2144-07-09 12:12:00",
      "speaker": "Patient",
      "text": "Thanks, Doctor."
    },
    {
      "turn_number": 73,
      "time": "2144-07-09 12:14:00",
      "speaker": "Doctor",
      "text": "Nurse will wheel you out now."
    },
    {
      "turn_number": 74,
      "time": "2144-07-09 12:15:00",
      "speaker": "Patient",
      "text": "Okay, let’s go."
    },
    {
      "turn_number": 75,
      "time": "2144-07-09 12:17:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___."
    },
    {
      "turn_number": 76,
      "time": "2144-07-09 12:18:00",
      "speaker": "Patient",
      "text": "You too."
    },
    {
      "turn_number": 77,
      "time": "2144-07-09 12:20:00",
      "speaker": "Doctor",
      "text": "Remember to follow up with all your specialists."
    },
    {
      "turn_number": 78,
      "time": "2144-07-09 12:21:00",
      "speaker": "Patient",
      "text": "I won’t miss them."
    },
    {
      "turn_number": 79,
      "time": "2144-07-09 12:23:00",
      "speaker": "Doctor",
      "text": "Call us if you have any issues with the stoma or pain."
    },
    {
      "turn_number": 80,
      "time": "2144-07-09 12:24:00",
      "speaker": "Patient",
      "text": "I will. Thanks again for everything."
    },
    {
      "turn_number": 81,
      "time": "2144-07-09 12:26:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Get some rest at home."
    },
    {
      "turn_number": 82,
      "time": "2144-07-09 12:27:00",
      "speaker": "Patient",
      "text": "I plan to."
    },
    {
      "turn_number": 83,
      "time": "2144-07-09 12:29:00",
      "speaker": "Doctor",
      "text": "We’ll talk soon."
    },
    {
      "turn_number": 84,
      "time": "2144-07-09 12:30:00",
      "speaker": "Patient",
      "text": "Take care."
    },
    {
      "turn_number": 85,
      "time": "2144-07-09 12:32:00",
      "speaker": "Doctor",
      "text": "Bye for now."
    }
  ],
  "summary": {
    "admission_start": "2144-06-28 10:30:00",
    "admission_end": "2144-07-09 15:44:00",
    "summary_paragraph": "Mr. ___ was admitted for ileal conduit urinary diversion due to severe urinary incontinence causing recurrent skin breakdown and stage IV pressure ulcers. The surgery was performed successfully, and he recovered without intraoperative complications. Post-operatively, he developed a fever on POD4, prompting a CT scan that showed nonspecific post-surgical changes without abscess or pneumonia. Urine culture grew E. coli, leading to a seven-day course of meropenem. His white count improved, and he transitioned from IV to oral pain medication. The NG tube was removed on POD2, diet advanced, and ostomy care was taught. On POD11, ureteral stents and the PICC line were removed, staples were replaced with Steri-Strips, and he was discharged home with visiting nurse services. He refused Bactrim initiation in the hospital but agreed to take it at home. Follow-up was arranged with urology, plastics, and primary care.",
    "problems": [
      "Neurogenic bladder NOS",
      "Pressure ulcer, stage IV",
      "Unspecified osteomyelitis, pelvic region and thigh",
      "Pressure ulcer, hip",
      "Paraplegia",
      "Urinary tract infection, site not specified",
      "Hypospadias",
      "Other and unspecified Escherichia coli [E. coli]",
      "Chronic kidney disease, unspecified",
      "Anxiety state, unspecified",
      "Other chronic pain",
      "Insomnia, unspecified",
      "Mechanical complication due to urethral (indwelling) catheter",
      "Other urinary incontinence"
    ]
  }
}
